        if(!CompanyRequestScope::sealedFor($ci)){show_error('Contexto indisponível.',503);return;}$ci->output->set_header('Cache-Control: no-store');require_once APPPATH.'services/CompanyPostRefundManual.php';$ctx=CompanyRequestScope::context();$issuer=$ctx->issuerId();$actor=$ctx->staffId();$csrf=$ci->session->userdata('native_post_refund_manual_csrf');if(!is_string($csrf)||!preg_match('/^[a-f0-9]{64}$/D',$csrf)){$csrf=bin2hex(random_bytes(32));$ci->session->set_userdata('native_post_refund_manual_csrf',$csrf);}$service=new CompanyPostRefundManual($ci->db,db_prefix());$detail=null;$error=null;
